def tuple_to_dict(t):
    """Convert a tuple of even length into a dict using adjacent elements as key-value pairs."""
    if len(t) % 2 != 0:
        raise ValueError("Tuple must contain an even number of elements.")

    return {t[i]: t[i + 1] for i in range(0, len(t), 2)}


# Example usage and assertion
if __name__ == "__main__":
    assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}
    print("Assertion passed!")

